// Plugin junkd's one hooks module: handoff, orch and tldr, the core setting and the /junkd frame, each in its own
// files, composed here. A feature file exports `register<Feature>(on, options)` for the hooks only it has, and plain
// named functions for the rest (see feature.ts); this file holds what is shared:
// - `$.junkd`, the noun other mods call (types/index.d.ts): schema answers here; get, set, config, open and
//   orchGuardState need `$`, which a noun may not capture, so the hooks on junkd.<method> below answer them.
// - session.start, tool.call and the PromptHint render: the host takes one hook per event and filter from a
//   module (a repeat `on` fails the load), and more than one feature needs each of them.
// - handoff.tsx: /junkd:handoff, /junkd:handon, /junkd:ahandoff, the auto handoff loop, the 🪃 segment, its pane.
// - orch.tsx: the main-loop guard (tool.call, agent.spawn), /junkd:orch panel and its pane.
// - tldr.tsx: /junkd:tldr's sentences and the terse flag file bin/tldr-hook reads.
// - core.ts: the core rows: output_style (and the flag file scripts/setup.sh reads), cache_check_sessions.
// - cache.tsx: the prompt-cache check at session start (scripts/cache-check.sh) and its band above the prompt.
// - panel.tsx: /junkd, ✚ junkd and the set of tabs (junkd, handoff, orch).
// Settings: one userConfig row per `<group>_<field>` (settings.ts), the /config row `junkd.<group>_<field>`.
// Paths follow CLAUDE_CONFIG_DIR like Claude Code itself; the flag files live under its junkd/ folder.
import type { Register } from 'claude-code'
import type { JunkdHandoffRoute } from '../types'
import { registerCache } from './cache'
import { coreStart, registerCore } from './core'
import { allSettings, getSetting, openPane, setSetting } from './dispatch'
import { handoffSegment, handoffStart, handoffStatus, handoffToolCall, registerHandoff } from './handoff'
import { orchCatchDeny, orchGuardState, orchStart, orchToolDeny, registerOrch } from './orch'
import { panelButton, panelStart, panelToggle, registerPanel } from './panel'
import { SCHEMA, isKey } from './settings'
import { registerTldr, tldrStart } from './tldr'

const NO_HOOK = 'junkd: the hooks module did not answer'
const ROUTES: readonly JunkdHandoffRoute[] = ['auto', 'handoffs', 'settings']
const reason = (err: unknown) => (err as Error)?.message ?? String(err)

export const register: Register = (on, options) => {
  // `$.junkd`. The host hands a noun's method one input and forbids the noun capturing `$`: schema and handoffStatus
  // need none and answer here; the rest throw unless the hooks below answer (they always do while this module runs).
  on('engine.create', async (_$, e, next) => ({
    ...(await next(e)),
    junkd: {
      schema: async () => SCHEMA.map(f => ({ ...f, ...(f.options ? { options: [...f.options] } : {}) })),
      config: async () => { throw new Error(NO_HOOK) },
      get: async () => { throw new Error(NO_HOOK) },
      set: async () => { throw new Error(NO_HOOK) },
      open: async () => { throw new Error(NO_HOOK) },
      handoffStatus: async () => handoffStatus(),
      orchGuardState: async () => { throw new Error(NO_HOOK) },
    },
  }))
  // A `{ deny }` here rejects the caller's promise with the reason (the host's own rule for a noun's event).
  on('junkd.get', async ($, e) => {
    if (!isKey(e?.key)) return { deny: `junkd: no setting ${String(e?.key)}` }
    try {
      return { value: await getSetting($, e.key) }
    } catch (err) {
      return { deny: reason(err) }
    }
  })
  on('junkd.set', async ($, e) => {
    if (!isKey(e?.key)) return { deny: `junkd: no setting ${String(e?.key)}` }
    if (e.scope !== undefined && e.scope !== 'user') return { deny: `junkd: scope ${String(e.scope)} is not supported yet` }
    try {
      const r = await setSetting($, e.key, e.value)
      return r.deny !== undefined ? { deny: r.deny } : { value: r.value }
    } catch (err) {
      return { deny: reason(err) }
    }
  })
  on('junkd.config', async $ => {
    try {
      return { value: await allSettings($) }
    } catch (err) {
      return { deny: reason(err) }
    }
  })
  on('junkd.open', async ($, e) => {
    const pane = e?.pane
    const route = e?.route
    if (route !== undefined && !ROUTES.includes(route)) return { deny: `junkd: no tab ${String(route)}` }
    try {
      if (pane === 'junkd') {
        if (route !== undefined) return { deny: `junkd: the junkd pane has no tab ${String(route)}` }
        await panelToggle($)
      } else if (pane === 'handoff' || pane === 'orch') await openPane($, pane, route === undefined ? {} : { route })
      else return { deny: `junkd: no pane ${String(pane)}` }
    } catch (err) {
      return { deny: reason(err) }
    }
    return { value: undefined }
  })
  on('junkd.orchGuardState', async $ => ({ value: await orchGuardState($) }))

  // Every feature's start, side by side; one that fails leaves the others started, and its error is raised after.
  on('session.start', async ($, e, next) => {
    const failed = (await Promise.allSettled([coreStart($), handoffStart($), orchStart($), tldrStart($), panelStart($)])).find(
      r => r.status === 'rejected',
    )
    if (failed) throw failed.reason
    return next(e)
  })

  // orch's guard first (the model's own calls only), then handoff's gate past the context threshold. A hook that
  // throws is skipped and the tool runs: the .catch refuses instead while the guard holds the main loop.
  on('tool.call', async ($, e, next) => {
    const deny = next.origin.plugin === 'engine' ? await orchToolDeny($, e) : undefined
    if (deny) return { deny }
    return handoffToolCall($, e, next)
  }).catch(($, e, next) => {
    if (next.called) return next(e)
    const deny = orchCatchDeny(e.agentId)
    return deny ? { deny } : next(e)
  })

  // What is beneath (another plugin's hint, or the engine's own line), then 🪃 (handoff) and ✚ junkd, side by side.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const { Box } = $.ui.resolve(e)
    const below = await next(e).catch(() => undefined)
    const parts = [below, handoffSegment($, e), panelButton($, e)].filter(Boolean)
    if (parts.length === 1) return parts[0]!
    return (
      <Box flexDirection="row" gap={2}>
        {parts}
      </Box>
    )
  })

  registerCore(on, options)
  registerCache(on, options)
  registerHandoff(on, options)
  registerOrch(on, options)
  registerTldr(on, options)
  registerPanel(on, options)
}

files.hooks/cache.tsx:
// cache: the prompt-cache check. At every main session start but a compaction (a new session, /clear, a resume),
// scripts/cache-check.sh reads the newest `core_cache_check_sessions` sessions of the session's project folder and
// prints one suggestion line or nothing; the line is drawn in a band above the prompt until it is dismissed or the
// next check replaces it. A failure goes to the debug log alone; nothing reaches the model or the screen.
import type { On } from 'claude-code'
import { C } from './cache-lib'
import type { $ } from './feature'
import { P } from './junkd-views'

// The check's line for the band; '' while there is none or it was dismissed.
let cacheLine = ''

// The script caps itself at 3 s in its own process group; the module's own timeout is the backstop above it.
const TIMEOUT_MS = 5_000

// scripts/cache-check.sh over the project folder <dir> (0 sessions: off). The last session's line never outlives it.
export async function cacheCheck($: $, dir: string): Promise<void> {
  const had = cacheLine !== ''
  cacheLine = ''
  try {
    if (had) $.ui.invalidate('ui.render')
    if (!C.sessions) return
    const r = await $.process.run([`${$.plugin.root}/scripts/cache-check.sh`, String(C.sessions), dir], { timeoutMs: TIMEOUT_MS })
    if (r.exitCode !== 0) throw new Error(`exit ${r.exitCode}: ${r.stderr.trim()}`)
    cacheLine = r.stdout.trim()
    if (cacheLine) $.ui.invalidate('ui.render')
  } catch (err) {
    $.ui.log(`junkd cache check: ${(err as Error)?.message ?? String(err)}`, { to: 'debug' })
  }
}

export function registerCache(on: On, _options: Record<string, unknown>): void {
  // classic.SessionStart, not session.start: it fires after /clear too and carries agent_id. The project folder is
  // the transcript's, exact where a slug of the cwd is not (a hashed long path, non-ASCII). Detached: the session
  // never waits on it.
  on('classic.SessionStart', ($, e, next) => {
    if (!e.agent_id && e.source !== 'compact') void cacheCheck($, e.transcript_path.replace(/\/[^/]*$/, ''))
    return next(e)
  })

  // The line above the prompt, under what is beneath (another plugin's band); a survey has the band alone. A
  // warning: bold, in the theme's warning colour, in a round border of it, with a dismiss button.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!cacheLine || e.props.hasSurvey) return next(e)
    const { Box, Button, Text } = $.ui.resolve(e)
    const below = await next(e).catch(() => undefined)
    const line = (
      <Box key="cache-check" flexDirection="row" gap={1} borderStyle="round" borderColor={P.warn} paddingX={1}>
        <Text color={P.warn} bold>
          ⚠️ {cacheLine}
        </Text>
        <Button key="cache-dismiss" role="dismiss" label="dismiss" onPress={() => { cacheLine = ''; $.ui.invalidate('ui.render') }}>
          ✕
        </Button>
      </Box>
    )
    return below ? (
      <Box flexDirection="column">
        {below}
        {line}
      </Box>
    ) : (
      line
    )
  })
}

files.hooks/core.ts:
// core: the `core` settings group, two rows.
// - output_style (ste|off). The setup step (scripts/setup.sh, SessionStart) is off while the flag file
//   ${CLAUDE_CONFIG_DIR:-$HOME/.claude}/junkd/output-style-off exists: a shell hook reads no `$.config`, so the row's
//   truth is mirrored there, at every write to the row and at session start. `ste` (the default) or `off`, as the
//   manifest's options; nothing else is taken.
// - cache_check_sessions (0-30, a whole number): how many sessions the prompt-cache check (cache.tsx) reads, 0 = off.
//   Kept in cache-lib.ts's C; no flag file (the module runs the script itself).
import type { On } from 'claude-code'
import type { JunkdStyle } from '../types'
import { C, applyCacheSettings, coerceSessions } from './cache-lib'
import type { $, SetResult } from './feature'
import { configKey, configKeys, fieldOf, groupOptions, keyOf } from './settings'

let styleIsOff = false

const STYLE_ERROR = (raw: unknown) => `junkd: ${String(raw)} is not a valid output_style (ste or off)`
function coerceStyle(raw: unknown): { value: JunkdStyle; error?: undefined } | { error: string; value?: undefined } {
  const v = String(raw).trim().toLowerCase()
  return v === 'ste' || v === 'off' ? { value: v } : { error: STYLE_ERROR(raw) }
}

let home = ''
async function homeDir($: $): Promise<string> {
  if (home) return home
  home = (await $.env.get('HOME')) ?? ''
  if (!home) home = (await $.process.run(['sh', '-c', 'echo $HOME'])).stdout.trim()
  return home
}
async function configDir($: $) {
  return (await $.env.get('CLAUDE_CONFIG_DIR')) || `${await homeDir($)}/.claude`
}

async function writeStyleFlag($: $): Promise<void> {
  const flag = `${await configDir($)}/junkd/output-style-off`
  if (styleIsOff) await $.fs.write(flag, '')
  else await $.process.run(['rm', '-f', '--', flag])
}

export async function coreGet(_$: $, field: string): Promise<JunkdStyle | number> {
  if (field === 'cache_check_sessions') return C.sessions
  return styleIsOff ? 'off' : 'ste'
}

// The host sends our own `$.config.set` past our config.set hook, so the flag is written here too.
export async function coreSet($: $, field: string, raw: unknown): Promise<SetResult> {
  if (field === 'cache_check_sessions') {
    const n = coerceSessions(raw)
    if (n.error !== undefined) return { deny: n.error }
    const r = await $.config.set({ key: configKey('core_cache_check_sessions'), value: n.value })
    if (r.deny !== undefined) return { deny: r.deny }
    C.sessions = n.value
    return { value: n.value }
  }
  if (field !== 'output_style') return { deny: `junkd: no setting ${keyOf('core', field)}` }
  const c = coerceStyle(raw)
  if (c.error !== undefined) return { deny: c.error }
  const { deny } = await $.config.set({ key: configKey('core_output_style'), value: c.value })
  if (deny !== undefined) return { deny }
  styleIsOff = c.value === 'off'
  await writeStyleFlag($)
  return { value: c.value }
}

export async function coreStart($: $): Promise<void> {
  await writeStyleFlag($).catch(() => undefined)
}

export function registerCore(on: On, options: Record<string, unknown>): void {
  // A value the manifest's options do not name (an edit of the file by hand) is the default, ste.
  const o = groupOptions(options, 'core')
  styleIsOff = coerceStyle(o.output_style).value === 'off'
  applyCacheSettings(o.cache_check_sessions)

  // The /config menu's writes to the core rows land here. cache_check_sessions: read as `set` reads it, refused where
  // `set` refuses. output_style: a value the options do not name is refused, one the row took is mirrored into the
  // flag file.
  on('config.set', { key: configKeys('core') }, async ($, e, next) => {
    const field = fieldOf('core', e.key)
    if (field === 'cache_check_sessions') {
      const n = coerceSessions(e.value)
      if (n.error !== undefined) return { deny: n.error }
      const r = await next({ ...e, value: n.value })
      if (r.deny === undefined) C.sessions = n.value
      return r
    }
    if (field !== 'output_style') return next(e)
    const c = coerceStyle(e.value)
    if (c.error !== undefined) return { deny: c.error }
    const r = await next({ ...e, value: c.value })
    if (r.deny === undefined) {
      styleIsOff = c.value === 'off'
      await writeStyleFlag($)
    }
    return r
  })
}

files.hooks/dispatch.ts:
// From a settings key or a pane name to the feature that owns it. The engine follows `$` into another file's
// function only when it is called by name, so each group is spelled out with its own `if` (see feature.ts).
import type { JunkdKey, JunkdValue } from '../types'
import { coreGet, coreSet } from './core'
import type { $, HideInput, OpenInput, SetResult, ShowInput } from './feature'
import { handoffGet, handoffHide, handoffOpen, handoffSet, handoffShow } from './handoff'
import { orchGet, orchHide, orchOpen, orchSet, orchShow } from './orch'
import { SCHEMA, entryOf } from './settings'
import { tldrGet, tldrSet } from './tldr'

export type FeaturePane = 'handoff' | 'orch'

// One row's current value. The key is a row of SCHEMA (the caller checked).
export async function getSetting($: $, key: JunkdKey): Promise<JunkdValue> {
  const { group, field } = entryOf(key)
  if (group === 'core') return coreGet($, field)
  if (group === 'handoff') return handoffGet($, field)
  if (group === 'orch') return orchGet($, field)
  return tldrGet($, field)
}

// Validates, writes the row and applies it: the feature's own rules. The key is a row of SCHEMA (the caller checked).
export async function setSetting($: $, key: JunkdKey, raw: unknown): Promise<SetResult> {
  const { group, field } = entryOf(key)
  if (group === 'core') return coreSet($, field, raw)
  if (group === 'handoff') return handoffSet($, field, raw)
  if (group === 'orch') return orchSet($, field, raw)
  return tldrSet($, field, raw)
}

// Every row's current value, by key, in manifest order.
export async function allSettings($: $): Promise<Record<JunkdKey, JunkdValue>> {
  const out = {} as Record<JunkdKey, JunkdValue>
  for (const f of SCHEMA) out[f.key] = await getSetting($, f.key)
  return out
}

export async function showPane($: $, pane: FeaturePane, input: ShowInput = {}): Promise<void> {
  if (pane === 'handoff') return handoffShow($, input)
  return orchShow($, input)
}
export async function hidePane($: $, pane: FeaturePane, input: HideInput = {}): Promise<void> {
  if (pane === 'handoff') return handoffHide($, input)
  return orchHide($, input)
}
export async function openPane($: $, pane: FeaturePane, input: OpenInput = {}): Promise<void> {
  if (pane === 'handoff') return handoffOpen($, input)
  return orchOpen($, input)
}

files.hooks/handoff.tsx:
// handoff: /junkd:handoff, /junkd:handon, /junkd:ahandoff, the auto handoff loop (a context threshold, the 5h-limit
// resume), the 🪃 segment and its pane. The `$`-free parts are handoff-lib.ts (state, options), handoff-ui.tsx and
// handoff-views.tsx (the pane). index.tsx runs handoffStart at session start, handoffToolCall inside the one tool.call
// hook and handoffSegment inside the one PromptHint render.
import { atom, update } from 'claude-code'
import type { Next, On, RenderInput, RenderSurface, ToolCallInput } from 'claude-code'

import type { JunkdAhandoff as Ahandoff } from '../types'
import type { HideInput, OpenInput, SetResult, ShowInput } from './feature'
import { configKey, configKeys, fieldOf, groupOptions, keyOf } from './settings'
import { DAY, DEFAULT_PROMPT, LIMIT_GRACE, LIMIT_PROMPT, S, coerce, current, idOf, isField, limit, loadOptions, status, type $, type Entry, type Field, type Route } from './handoff-lib'
import { Footer, P, Rule, TABS, Tabs, fields, type Api, type Ctx, type Elements } from './handoff-ui'
import { VIEWS } from './handoff-views'

const PANE = 'ahandoff'
const EDGE = 2 // empty columns at the pane's right edge (a docked pane's last column may not show)
const HANDOFF_FILE = /\/handoffs\/[^/]+\.md$/
// What arming says while the `enabled` setting is off; /junkd:handoff, /junkd:handon and the pane keep working.
const OFF = 'handoff: auto handoff is disabled (the enabled setting is off: /config, or the pane\'s Settings tab)'

function redraw($: $) {
  $.ui.invalidate('ui.render')
}

const STORE = 'ahandoff'

const view = atom({ plugin: 'junkd', key: 'ahandoff' } as const, {
  on: false, phase: 'idle', percent: 0, threshold: 85, checkEvery: 5,
  prompt: '', lastId: '', count: 0, route: 'auto', paneOpen: false,
} satisfies Ahandoff)

// ponytail: plugin commands are namespaced (`junkd:handon`) — junkd's own first, else any plugin's by suffix.
async function findCommand($: $, suffix: 'handoff' | 'handon'): Promise<string> {
  const names = (await $.command.list()).map(c => c.name)
  return names.find(n => n === `junkd:${suffix}`) ?? names.find(n => n.endsWith(`:${suffix}`)) ?? `junkd:${suffix}`
}

let home = ''
async function homeDir($: $): Promise<string> {
  if (home) return home
  home = (await $.env.get('HOME')) ?? ''
  if (!home) home = (await $.process.run(['sh', '-c', 'echo $HOME'])).stdout.trim()
  return home
}

// Where bin/handoff-path writes: `${CLAUDE_CONFIG_DIR:-$HOME/.claude}/handoffs` (unset or empty: the home's .claude).
async function handoffDir($: $): Promise<string> {
  return `${(await $.env.get('CLAUDE_CONFIG_DIR')) || `${await homeDir($)}/.claude`}/handoffs`
}

async function listHandoffs($: $, force?: boolean): Promise<Entry[]> {
  if (S.entries && !force) return S.entries
  const dir = await handoffDir($)
  const home = await homeDir($)
  S.dir = home && dir.startsWith(`${home}/`) ? `~${dir.slice(home.length)}` : dir
  let files: Awaited<ReturnType<$['fs']['list']>> = []
  try {
    files = await $.fs.list(dir)
  } catch {
    files = [] // ponytail: no folder yet = no handoffs
  }
  const now = Date.now()
  const entries = await Promise.all(
    files
      .filter(f => f.kind === 'file' && f.name.endsWith('.md'))
      .map(async f => {
        const path = `${dir}/${f.name}`
        let title = ''
        try {
          title = (await $.fs.read(path)).split('\n').find(l => l.startsWith('# '))?.slice(2).trim() ?? ''
        } catch {}
        return { id: idOf(f.name) ?? f.name.replace(/\.md$/, ''), path, mtimeMs: f.mtimeMs, title, stale: now - f.mtimeMs > S.staleDays * DAY }
      }),
  )
  S.entries = entries.sort((a, b) => b.mtimeMs - a.mtimeMs)
  return S.entries
}

// Mirror S into $.state and redraw the pane and the segment.
function sync($: $, percent?: number) {
  if (percent !== undefined) S.percent = percent
  $.ui.invalidate('ui.render')
  return update($, view, v => ({
    ...v, on: S.armed, phase: S.phase, prompt: S.prompt, lastId: S.lastId ?? '', count: S.count,
    threshold: S.threshold, checkEvery: S.checkEvery, percent: S.percent, route: S.route, paneOpen: S.paneOpen,
  }))
}

function persist($: $) {
  return $.store.set(STORE, {
    on: S.armed, prompt: S.prompt,
    pending: S.phase === 'resume' && S.lastId ? { id: S.lastId, prompt: S.prompt } : undefined,
    resumeAt: S.blocked ? S.resumeAt : undefined,
  })
}

// A turn died on the 5h limit: one timer to 2 min past the window's reset, then the continuation prompt.
// ponytail: no 5h interval — the next limit hit schedules the next timer. The timer lives in this
// process only; after a restart session.start just tells you it was pending.
let limitTimer: { cancel(): void } | null = null
async function scheduleResume($: $) {
  if (S.blocked || !S.resetsAt) return
  S.blocked = true
  S.resumeAt = Date.parse(S.resetsAt) + LIMIT_GRACE
  const delay = Math.max(0, S.resumeAt - (await $.clock.now()))
  limitTimer = $.clock.after(delay, () => void resumeAfterLimit($))
  await persist($)
  $.ui.toast(`handoff: 5h limit hit — resuming at ${hhmm(S.resumeAt)}`)
  await sync($)
}
async function resumeAfterLimit($: $) {
  limitTimer = null
  if (!S.blocked) return
  S.blocked = false
  S.resumeAt = null
  await persist($)
  await sync($)
  if (S.armed) await sendPrompt($, S.prompt === DEFAULT_PROMPT ? LIMIT_PROMPT : S.prompt)
}
function cancelResume() {
  limitTimer?.cancel()
  limitTimer = null
  S.blocked = false
  S.resumeAt = null
}
const hhmm = (ms: number) => new Date(ms).toTimeString().slice(0, 5)


// A handoff file written this session: its id becomes the last one, the list is read again.
function record(path: string) {
  const name = path.replace(/^.*\//, '')
  const id = idOf(name) ?? name.replace(/\.md$/, '')
  S.lastId = id
  if (!S.session.includes(id)) S.session.push(id)
  S.entries = null
  return id
}

async function load($: $) {
  if (S.entries === null) {
    await listHandoffs($)
    redraw($)
  }
}

// /junkd:handoff in the next turn. ponytail: detached — $.command.run is refused inside a hook the turn waits on.
function queueHandoff($: $) {
  void $.clock.sleep(0).then(async () => $.command.run({ command: await findCommand($, 'handoff') }))
}

// /clear → /junkd:handon <id> → the continuation prompt, detached like queueHandoff.
// A slash prompt cannot ride along as text (the host refuses it and the model would only read it),
// so it runs as the command itself right after /junkd:handon.
function continueFrom($: $, id: string) {
  const text = S.prompt || DEFAULT_PROMPT
  void $.clock.sleep(0).then(async () => {
    S.fresh = S.armed // the guard is the loop's: a manual resume while off needs none
    S.phase = 'clear'
    // ponytail: queue /clear before any other await — a headless session exits right after the turn.
    const cleared = $.command.run({ command: 'clear' })
    void sync($)
    await cleared
    S.phase = 'resume'
    void sync($)
    await $.command.run({ command: await findCommand($, 'handon'), args: id })
    S.phase = 'idle'
    await persist($)
    await sync($, 0)
    await sendPrompt($, text)
  })
}

// Runs the armed prompt as the next turn, detached like queueHandoff ($.prompt.submit is refused
// inside a hook the turn waits on). The host refuses a submitted text starting with /, so a slash
// command goes through $.command.run instead.
function runPrompt($: $, text: string) {
  void $.clock.sleep(0).then(() => sendPrompt($, text))
}
async function sendPrompt($: $, text: string) {
  const [, command, args = ''] = /^\/(\S+)\s*([\s\S]*)$/.exec(text) ?? []
  await (command ? $.command.run({ command, args }) : $.prompt.submit({ text }))
}

async function panel($: $) {
  await toggle($)
  return {}
}
async function auto($: $, prompt: string, pane = true) {
  if (!S.enabled) return { text: OFF }
  // the pane opens first: only an open made while the command runs is placed at any width
  const opened = pane ? openPane($, 'auto') : undefined
  await arm($)
  await opened
  if (!prompt) return { text: `handoff auto on — threshold ${S.threshold}%` }
  runPrompt($, prompt)
  return { text: `handoff auto on — threshold ${S.threshold}% — running: ${prompt}` }
}
async function off($: $) {
  await disarm($)
  return { text: 'handoff auto off.' }
}

// Who opened the pane through handoffShow({ owner }) (the /junkd set of panes); any other open or close clears
// it, so `hide({ owner })` closes only a pane that owner opened and nobody reopened since.
let owner: string | undefined

// `$.ui.open` before any await: only an open made while the press or command runs counts as asked.
async function openPane($: $, route?: Route, focus = true) {
  const opened = $.ui.open({ id: PANE, title: 'handoff', focus: focus || undefined })
  owner = undefined
  if (route) S.route = route
  S.paneOpen = (await opened).isPlaced
  await sync($)
  void load($)
}

// The engine does not raise our own `$.ui.close` to our `ui.close` hook, so we clear the flag here.
async function closePane($: $) {
  S.paneOpen = false
  owner = undefined
  await $.ui.close({ id: PANE })
  await sync($)
}

function toggle($: $, route?: Route) {
  return S.paneOpen ? closePane($) : openPane($, route)
}

async function arm($: $) {
  if (!S.enabled) {
    S.note = `✗ ${OFF}`
    return void redraw($)
  }
  S.armed = true
  S.phase = 'idle'
  S.calls = 0
  S.armedAt = Date.now()
  await persist($)
  await sync($)
}

// Drops the cycle too: a handoff written but not yet acted on, and the fresh-window guard, are the old loop's.
async function disarm($: $) {
  S.armed = false
  cancelResume()
  S.phase = 'idle'
  S.written = null
  S.fresh = false
  S.armedAt = null
  await persist($)
  await sync($)
}

async function remove($: $, ids: string[]) {
  const entries = await listHandoffs($)
  const paths = entries.filter(x => ids.includes(x.id)).map(x => x.path)
  if (paths.length) await $.process.run(['rm', '--', ...paths])
  S.entries = null
  S.confirm = null
  await listHandoffs($)
  return paths.length
}

// Writes one field to its `/config` row (`junkd.handoff_<field>`) and mirrors it into S. `{ deny }` when the value
// does not fit or a hook refused; the pane's note says which either way.
async function setOption($: $, field: Field, raw: string | number | boolean) {
  const c = coerce(field, raw)
  if (c.error !== undefined) {
    S.note = `✗ ${c.error}`
    redraw($)
    return { deny: c.error }
  }
  const value = c.value
  const { deny } = await $.config.set({ key: configKey(keyOf('handoff', field)), value })
  if (deny) {
    S.note = `✗ ${deny}`
    redraw($)
    return { deny }
  }
  S.note = `✓ ${field} = ${String(value)}`
  await apply($, field, value)
  return { value: current(field) } as const
}

// One field as its row took it, into S — the one place a write lands, from setOption or the /config menu's hook.
async function apply($: $, field: Field, value: number | boolean) {
  if (field === 'threshold') S.threshold = value as number
  else if (field === 'checkEvery') S.checkEvery = value as number
  else if (field === 'staleDays') { S.staleDays = value as number; S.entries = null; void load($) }
  else if (field === 'segment') S.segment = value as boolean
  else if (field === 'autoOn') S.autoOn = value as boolean
  else if (field === 'resumeAfterLimit') { S.resumeAfterLimit = value as boolean; if (!value) cancelResume() }
  else if (field === 'enabled') await applyEnabled($, value as boolean)
  await sync($)
}

// `enabled` as the row took it. Off disarms the loop (and drops a pending 5h-limit resume), and arm() refuses while
// it is off, so the loop's hooks need only `S.armed`. On arms nothing: the loop waits for /junkd:ahandoff (autoOn arms at
// load only).
async function applyEnabled($: $, on: boolean) {
  S.enabled = on
  if (!on && S.armed) await disarm($)
}

function api($: $): Api {
  return {
    go: route => {
      S.route = route
      S.note = ''
      S.confirm = null
      S.viewing = null
      void sync($)
      void load($)
    },
    arm: () => arm($),
    disarm: () => void disarm($),
    handoffNow: async () => {
      if (S.armed) S.phase = 'handoff'
      S.note = '✓ handoff queued'
      queueHandoff($)
      await sync($)
    },
    resume: async id => continueFrom($, id),
    handon: async id => {
      await $.command.run({ command: await findCommand($, 'handon'), args: id })
    },
    copy: async (id, surface) => {
      const r = await $.ui.copy({ text: id, surface: surface as RenderSurface })
      S.note = r.isCopied ? `✓ copied ${id}` : `✗ could not copy ${id}`
      redraw($)
    },
    remove: async id => {
      S.note = (await remove($, [id])) ? `✓ deleted ${id}` : `✗ ${id} not found`
      redraw($)
    },
    deleteStale: async () => {
      const stale = (await listHandoffs($, true)).filter(x => x.stale).map(x => x.id)
      S.note = `✓ deleted ${await remove($, stale)} stale handoff(s)`
      redraw($)
    },
    openFolder: async () => {
      const r = await $.process.run(['open', await handoffDir($)])
      if (r.exitCode !== 0) S.note = `✗ ${r.stderr.trim() || 'could not open the folder'}`
      redraw($)
    },
    set: async (field, value) => { await setOption($, field, value) },
    refresh: () => {
      redraw($)
      void load($)
    },
  }
}

// ------------------------------------------------------------------ what index.tsx and dispatch.ts call

const checkRoute = (route: unknown) => {
  if (route !== undefined && !TABS.some(t => t[2] === route)) throw new Error(`handoff: no tab ${String(route)}`)
}

export async function handoffGet(_$: $, field: string): Promise<number | boolean> {
  return current(field as Field)
}
export async function handoffSet($: $, field: string, raw: unknown): Promise<SetResult> {
  if (!isField(field)) return { deny: `junkd: no setting ${keyOf('handoff', field)}` }
  const r = await setOption($, field, raw as string | number | boolean)
  return r.deny !== undefined ? { deny: r.deny } : { value: r.value }
}
// A route while the pane is up switches its tab; otherwise the call toggles the pane, as /junkd:handoff panel does.
export async function handoffOpen($: $, input: OpenInput = {}): Promise<void> {
  const route = input.route
  checkRoute(route)
  if (route && S.paneOpen) {
    S.route = route
    await sync($)
    void load($)
  } else await toggle($, route)
}
// show never closes: the pane opens (or, up already, is asked again: retitled, its tab switched, the keys asked
// for), on `route` when given; `owner` marks it as that caller's, for hide.
export async function handoffShow($: $, input: ShowInput = {}): Promise<void> {
  checkRoute(input.route)
  const opened = openPane($, input.route, input.focus === true)
  owner = input.owner
  await opened
}
// hide closes the pane; with `owner`, only while the pane is still the one that owner's show opened.
export async function handoffHide($: $, input: HideInput = {}): Promise<void> {
  if (input.owner !== undefined && input.owner !== owner) return
  await closePane($)
}
export function handoffStatus() {
  return status()
}

export async function handoffStart($: $): Promise<void> {
  const saved = (await $.store.get(STORE)) as { on?: boolean; prompt?: string | null; pending?: { id: string }; resumeAt?: number } | undefined
  if (saved?.pending) $.ui.toast(`handoff: pending handoff ${saved.pending.id} — run /junkd:handon ${saved.pending.id}`)
  if (saved?.resumeAt && saved.resumeAt > Date.now()) {
    const how = S.enabled ? 're-arm with /junkd:ahandoff' : 'auto handoff is disabled: turn the enabled setting on (/config, or the pane\'s Settings tab), then /junkd:ahandoff'
    $.ui.toast(`handoff: a 5h-limit resume was due at ${hhmm(saved.resumeAt)} — ${how}`)
  }
  if (saved?.resumeAt) await $.store.set(STORE, { ...saved, resumeAt: undefined })
  await sync($)
}

export async function handoffToolCall($: $, e: ToolCallInput, next: Next<'tool.call'>) {
  if (e.agentId) return next(e)
  const isHandoffWrite = e.tool === 'Write' && HANDOFF_FILE.test(String(e.file_path))
  if (!S.armed) {
    if (!isHandoffWrite) return next(e)
    const r = await next(e)
    record(String(e.file_path))
    await sync($)
    return r
  }
  if (S.phase === 'idle' && !S.fresh && ++S.calls % S.checkEvery === 0) {
    const { context } = await $.session.usage()
    S.tokens = context.tokens ?? S.tokens
    const percent = context.percent ?? 0
    if (percent >= limit()) S.phase = 'handoff'
    await sync($, percent)
  }
  if (S.phase !== 'handoff') return next(e)
  const isHandoffPath = e.tool === 'Bash' && /handoff-path/.test(String(e.command))
  const isHandoffSkill = e.tool === 'Skill' && /handoff/.test(String((e as { skill?: unknown }).skill))
  if (isHandoffWrite) S.written = String(e.file_path)
  if (isHandoffWrite || isHandoffPath || isHandoffSkill) return next(e)
  return {
    deny: 'ahandoff: context limit reached. Stop the current work now. Call the Skill tool with skill "junkd:handoff" and follow it (run its bin/handoff-path, then Write the handoff markdown to the path it prints — include task ids, branch, worktree, round and what to do next). Then end the turn with one line. Every other tool is denied until the handoff is written.',
  }
}

// The status-line segment: 🪃 NN% (green, yellow within 10 points of the threshold, red past it). undefined while
// handoff is off or the segment setting is.
export function handoffSegment($: $, e: RenderInput<'PromptHint'>) {
  if (!S.enabled || !S.segment) return undefined
  const { Button, Text } = $.ui.resolve(e)
  const label = !S.armed
    ? '🪃 off'
    : S.blocked && S.resumeAt ? `🪃 limit → ${hhmm(S.resumeAt)}`
    : S.phase === 'handoff' ? '🪃 handoff…' : S.phase === 'idle' ? `🪃 ${S.percent}%` : '🪃 resume…'
  const color = !S.armed || S.phase !== 'idle'
    ? P.secondary
    : S.blocked ? P.warn
    : S.percent >= limit() ? P.bad : S.percent >= limit() - 10 ? P.warn : P.ok
  return (
    <Button key="handoff-segment" plain label={label} onPress={() => void toggle($)}>
      <Text color={color}>{label}</Text>
    </Button>
  )
}

export function registerHandoff(on: On, options: Record<string, unknown>): void {
  loadOptions(groupOptions(options, 'handoff'))

  // /junkd:handoff panel | auto [prompt] | off — anything else is the plain skill.
  on('command.run', { command: 'junkd:handoff' }, async ($, e, next) => {
    const [sub = '', ...rest] = e.args.trim().split(/\s+/)
    if (sub === 'panel') return panel($)
    if (sub === 'auto') return auto($, rest.join(' '))
    if (sub === 'off') return off($)
    return next(e)
  })

  // /junkd:ahandoff [prompt] | off | panel — the short form: anything else is the prompt. Its skill's text runs
  // only when this module is not loaded.
  on('command.run', { command: 'junkd:ahandoff' }, async ($, e) => {
    const args = e.args.trim()
    if (args === 'panel') return panel($)
    if (args === 'off') return off($)
    return auto($, args, false) // ponytail: the short form arms and runs the prompt; the pane is /junkd:ahandoff panel
  })

  // The /config menu's own writes to every handoff row pass here (a hook never sees its plugin's own
  // `$.config.set`): read as `set` reads it, refused where `set` refuses, and applied live once the row took it.
  on('config.set', { key: configKeys('handoff') }, async ($, e, next) => {
    const field = fieldOf('handoff', e.key)
    if (!isField(field)) return next(e)
    const c = coerce(field, e.value)
    if (c.error !== undefined) return { deny: c.error }
    const r = await next({ ...e, value: c.value })
    if (r.deny === undefined) await apply($, field, c.value)
    return r
  })

  on('turn.complete', async ($, e, next) => {
    if (!S.armed || e.agentId) return next(e)
    // ponytail: the host names no error kind here — an error with the 5h window at 99%+ is the limit.
    if (e.reason === 'error' && S.resumeAfterLimit && S.fiveHour >= 99) {
      await scheduleResume($)
      return next(e)
    }
    const { context } = await $.session.usage()
    S.tokens = context.tokens ?? S.tokens
    const percent = context.percent ?? 0
    if (S.fresh) {
      // nothing: the first measurement of the new window decides (session.measure)
    } else if (S.phase === 'handoff' && !S.written) {
      queueHandoff($) // model never wrote it mid-turn: ask /junkd:handoff as the next turn
    } else if (S.phase === 'idle' && percent >= limit()) {
      S.phase = 'handoff'
      queueHandoff($)
    } else if (S.phase === 'handoff' && S.written) {
      const id = record(S.written)
      S.written = null
      S.calls = 0
      S.count++
      S.phase = 'resume'
      await persist($)
      continueFrom($, id)
    }
    await sync($, percent)
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    const fiveHour = e.rateLimits.find(r => r.kind === 'five_hour')
    if (fiveHour) {
      S.fiveHour = fiveHour.percentUsed
      S.resetsAt = fiveHour.resetsAt ?? S.resetsAt
    }
    if (e.changed.includes('context')) {
      S.tokens = e.context.tokens ?? S.tokens
      const percent = e.context.percent ?? S.percent
      if (e.context.percent !== undefined && (S.fresh || !S.base)) {
        S.base = percent
        if (S.armed && S.fresh) {
          S.fresh = false
          if (limit() >= 100) {
            // ponytail: a limit no window can reach would never hand off — disarm instead.
            S.armed = false
            S.phase = 'idle'
            await persist($)
            $.ui.toast(`handoff: fresh window at ${percent}%, ${S.threshold} more points can't fit — auto disarmed`)
          } else if (S.threshold <= S.base) {
            $.ui.toast(`handoff: fresh window at ${percent}%, next handoff at ${limit()}%`)
          }
        }
      }
      await sync($, percent)
    }
    return next(e)
  })

  on('ui.focus', { requestId: PANE }, async ($, e, next) => {
    const r = await next(e)
    if (!r.deny) S.ring = e.element ?? null
    return r
  })

  // The person's closes (q, ✕) pass here; ours go through closePane.
  on('ui.close', { id: PANE }, async ($, e, next) => {
    S.paneOpen = false
    owner = undefined
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e, next) => {
    if (e.surface === 'mobile') return next(e)
    S.cols = Math.max(20, (e.props.bodyColumns ?? 100) - EDGE)
    const a = api($)
    const ui = fields($.ui.resolve(e) as Elements, a, e.surface, key => void $.ui.focus({ requestId: PANE, key }))
    const c: Ctx = { api: a, ui, surface: e.surface }
    const screen = VIEWS[S.route](c)
    // Docked, the pane is floor to ceiling: the body takes what is left, the footer sits at the bottom.
    const rows = e.props.placement === 'dock' ? e.props.scroll?.bodyRows : undefined
    return (
      <ui.Box flexDirection="column" paddingRight={EDGE} minHeight={rows}>
        <Tabs c={c} close={() => void closePane($)} />
        <Rule c={c} />
        <ui.Box flexDirection="column" flexGrow={1} marginTop={1}>
          {screen.body}
        </ui.Box>
        <Footer c={c} note={S.note || screen.note} hints={screen.keys} />
      </ui.Box>
    )
  })
}

