// tldr: the `tldr` settings group (enabled, terse, sentences) and /junkd:tldr's default sentence count. bin/tldr-hook
// (UserPromptSubmit, a shell hook: it reads no `$.config`) decides each turn from two flag files under
// ${CLAUDE_CONFIG_DIR:-$HOME/.claude}/junkd/: `tldr-on` is terse mode's truth (bin/tldr-flag writes it too, so terse
// is read from the file), `tldr-off` mirrors the enabled row (there while off). A write to either row, by
// `$.junkd.set` or by the /config menu, writes its flag file first; enabled's is mirrored again at session start.
import type { On } from 'claude-code'
import type { JunkdTldrField } from '../types'
import type { $, SetResult } from './feature'
import { configKey, configKeys, fieldOf, groupOptions, keyOf, rowsOf } from './settings'

type Field = JunkdTldrField
const isField = (key: unknown): key is Field => rowsOf('tldr').some(f => f.field === key)
const S = { enabled: true, sentences: 3 }

// The same spelling as bin/tldr-flag and bin/tldr-hook: ${CLAUDE_CONFIG_DIR:-$HOME/.claude}/junkd/<name>.
type Flag = 'tldr-on' | 'tldr-off'
async function flagPath($: $, name: Flag): Promise<string> {
  const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) || `${await $.env.get('HOME')}/.claude`
  return `${dir}/junkd/${name}`
}
// The flag file a field's row is mirrored into, and whether a value puts it there: terse on -> tldr-on, enabled off
// -> tldr-off. Sentences has none.
const FLAG_OF: Partial<Record<Field, { name: Flag; present: (value: boolean) => boolean }>> = {
  terse: { name: 'tldr-on', present: v => v },
  enabled: { name: 'tldr-off', present: v => !v },
}

// The hook sees presence only: the empty file, or none. Answers the reason when it could not.
async function writeFlag($: $, flag: string, present: boolean): Promise<string | undefined> {
  try {
    if (present) await $.fs.write(flag, '')
    else {
      const r = await $.process.run(['rm', '-f', '--', flag])
      if (r.exitCode !== 0) return `tldr: could not remove ${flag}: ${r.stderr.trim() || `rm exited ${r.exitCode}`}`
    }
  } catch (err) {
    return `tldr: could not write ${flag}: ${(err as Error)?.message ?? String(err)}`
  }
  return undefined
}

// A mirrored row, on either path: the flag file first, then the row (`store`). A flag that could not be written
// stores nothing; a refused row puts the flag back as it was.
async function writeMirrored<R extends { deny?: string }>($: $, flag: string, present: boolean, store: () => Promise<R>): Promise<R | { deny: string }> {
  const was = await $.fs.exists(flag)
  const failed = await writeFlag($, flag, present)
  if (failed !== undefined) return { deny: failed }
  const r = await store()
  if (r.deny !== undefined) await writeFlag($, flag, was)
  return r
}

// A row's write, its flag file first where it has one.
async function storeRow<R extends { deny?: string }>($: $, field: Field, value: number | boolean, store: () => Promise<R>): Promise<R | { deny: string }> {
  const mirror = FLAG_OF[field]
  if (mirror === undefined) return store()
  return writeMirrored($, await flagPath($, mirror.name), mirror.present(value === true), store)
}

// A raw value to the field's kind; `error` when it does not fit.
type Coerced = { value: number | boolean; error?: undefined } | { error: string; value?: undefined }
function coerce(key: Field, raw: unknown): Coerced {
  if (key === 'terse' || key === 'enabled') return { value: raw === true || raw === 'true' || raw === 'on' }
  const value = Number(raw)
  if (!Number.isInteger(value) || value < 1) return { error: `${String(raw)} is not a valid sentences (a whole number, 1 or more)` }
  return { value }
}

// What a stored row changes in memory.
function apply(field: Field, value: number | boolean): void {
  if (field === 'sentences') S.sentences = value as number
  if (field === 'enabled') S.enabled = value as boolean
}

export async function tldrGet($: $, field: string): Promise<number | boolean> {
  if (field === 'terse') return $.fs.exists(await flagPath($, 'tldr-on'))
  if (field === 'enabled') return S.enabled
  return S.sentences
}

export async function tldrSet($: $, field: string, raw: unknown): Promise<SetResult> {
  if (!isField(field)) return { deny: `junkd: no setting ${keyOf('tldr', field)}` }
  const c = coerce(field, raw)
  if (c.error !== undefined) return { deny: c.error }
  // The host sends this write through the other plugins' hooks and skips ours below, so the value is applied here.
  const { deny } = await storeRow($, field, c.value, () => $.config.set({ key: configKey(keyOf('tldr', field)), value: c.value }))
  if (deny !== undefined) return { deny }
  apply(field, c.value)
  return { value: c.value }
}

// The enabled row into tldr-off, as the options at load (or the last write) have it: a session started after a hand
// edit of settings.json, or after the flag was lost, puts the file back in step. A failure leaves the other starts be.
export async function tldrStart($: $): Promise<void> {
  try {
    await writeFlag($, await flagPath($, 'tldr-off'), !S.enabled)
  } catch {}
}

export function registerTldr(on: On, options: Record<string, unknown>): void {
  const o = groupOptions(options, 'tldr')
  S.sentences = coerce('sentences', o.sentences ?? 3).value as number ?? 3
  S.enabled = o.enabled !== false // the engine hands only a boolean (it refuses another type at load), or none: on

  // The /config menu's own writes to a tldr row land here (a hook never sees its plugin's own `$.config.set`):
  // read as `set` reads it, refused where `set` refuses; terse and enabled write their flag first as `set` does.
  on('config.set', { key: configKeys('tldr') }, async ($, e, next) => {
    const field = fieldOf('tldr', e.key)
    if (!isField(field)) return next(e)
    const c = coerce(field, e.value)
    if (c.error !== undefined) return { deny: c.error }
    const r = await storeRow($, field, c.value, () => next({ ...e, value: c.value }))
    if (r.deny === undefined) apply(field, c.value)
    return r
  })
  // `/junkd:tldr` with no argument: the sentences setting is the number the skill reads (its markdown's own "else 3"
  // is the default on the hosts without this module). A number, on, off, status pass as typed.
  on('command.run', { command: 'junkd:tldr' }, (_$, e, next) => next(e.args.trim() === '' ? { ...e, args: String(S.sentences) } : e))
}

files.hooks/cache-lib.ts:
// The prompt-cache check's setting, `$`-free: core.ts reads and writes it (the row is in the core group), cache.tsx
// runs the check with it. `core_cache_check_sessions`: how many of the project's newest sessions
// scripts/cache-check.sh reads, 0 = the check is off.
export const C = { sessions: 10 }
// A whole number in these bounds, as the manifest's min and max (the manifest has no "integer" field).
export const CACHE_RANGE = [0, 30] as const
const DEFAULT = 10

// A raw value (typed in the pane, handed to $.junkd.set, or written in the /config menu) to the row's number;
// `error` when it does not fit. The one check for every write path: a write is refused, never clamped.
export type Coerced = { value: number; error?: undefined } | { error: string; value?: undefined }
export function coerceSessions(raw: unknown): Coerced {
  const [lo, hi] = CACHE_RANGE
  const n = typeof raw === 'number' ? raw : typeof raw === 'string' && raw.trim() ? Number(raw) : NaN
  return Number.isInteger(n) && n >= lo && n <= hi ? { value: n } : { error: `junkd: ${String(raw)} is not a valid cache_check_sessions (a whole number ${lo}–${hi})` }
}

// The option the engine fills in from the manifest at load: rounded, a numeric string taken, out of range clamped,
// anything else the default (a load is no write, so nothing is refused).
export function applyCacheSettings(raw: unknown): void {
  const n = Math.round(typeof raw === 'number' ? raw : typeof raw === 'string' && raw.trim() ? Number(raw) : NaN)
  const [lo, hi] = CACHE_RANGE
  C.sessions = Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : DEFAULT
}

files.hooks/feature.ts:
// The shapes every feature file (core.ts, handoff.tsx, orch.tsx, tldr.tsx, panel.tsx) shares with index.tsx and
// dispatch.ts. `$`-free, types and constants only.
//
// The engine takes `$` into a function of another file only when that function is called by its own name
// (`handoffGet($, field)`), never through an object or a table (`SETTINGS[group].get($, ...)` fails the load). So
// each feature exports plain named functions, and dispatch.ts picks one with an `if` per group.
import type { EngineInterface } from 'claude-code'
import type { JunkdHandoffRoute, JunkdValue } from '../types'

export type $ = EngineInterface

// What a feature's `<feature>Set` answers: the value as stored (after coercion), or the refusal's reason.
export type SetResult = { value: JunkdValue; deny?: undefined } | { deny: string; value?: undefined }

// show opens a feature pane and never closes it: on `route` (handoff only); `focus` asks for the keys; `owner`
// marks it as that caller's. hide closes it; with `owner`, only while it is still the pane that owner's show opened
// (any other open or close since, the person's included, clears the mark). open toggles it, as /junkd:<feature>
// panel does; a `route` while the pane is up switches its tab instead. An unknown route throws its reason.
export type ShowInput = { route?: JunkdHandoffRoute; focus?: boolean; owner?: string }
export type HideInput = { owner?: string }
export type OpenInput = { route?: JunkdHandoffRoute }

// The owner mark the /junkd set puts on the feature panes it opens (panel.tsx).
export const SET_OWNER = 'junkd'

files.hooks/junkd-views.tsx:
// The /junkd pane's drawing, `$`-free: panel.tsx hands it the surface's elements, the pane's data and its actions
// as closures. Three sections: the marketplace's plugins (on/off at user scope), the main settings of every group of
// junkd (core, handoff, orch, tldr), the enabled plugins' commands.
import type { ElementTable, RenderChildren, RenderInput } from 'claude-code'

export type PluginRow = { name: string; description: string; isSelf: boolean; isUserOn: boolean; isActive: boolean }
// One `main` row of a group (settings.ts), by its field, with its current value beside it.
export type Field = { key: string; type: string; title: string; options?: readonly string[]; value: unknown }
export type Section = { group: string; fields: Field[]; hasPane: boolean }
export type Command = { name: string; description: string }
export type PanelData = {
  marketplace: string
  version: string // the marketplace checkout's short sha, '' when none
  settingsPath: string // the user-scope settings file, ~ for HOME
  plugins: PluginRow[]
  sections: Section[]
  commands: Command[]
  groups: readonly string[] // every settings group, in order: the Settings title, and the line drawn before the first read
  note: string
  isChanged: boolean
}
export type PanelActs = {
  close(): void
  togglePlugin(name: string): void
  set(group: string, field: string, value: unknown): void
  openPane(group: string): void
}
export type Els = Pick<ElementTable<'terminal'>, 'Box' | 'Text' | 'Button' | 'Input'>

const EDGE = 2 // a docked pane's last column may not show
// Theme keys only, never a hex value: the text follows the person's theme. The accent is junk-drawer's orange.
export const P = { accent: 'claude', secondary: 'inactive', dim: 'subtle', ok: 'success', warn: 'warning', bad: 'error' } as const
export const LETTERS = 'abcdefghijklmnoprstuvwxyz' // q closes
export const PLUGIN_KEYS = 9 // 1-9 flip a plugin; the tenth on has no hotkey

// The engine empties a field on Enter and redraws `value` only when it changed: a new key per Enter redraws it.
const entered: Record<string, number> = {}
export const fieldKey = (id: string) => (entered[id] ? `${id}~${entered[id]}` : id)

// A choice as Buttons, not the engine's Select: the current option an inverse block, every other a dim Button that
// picks it (the terminal Select opens on focus with the current option highlighted, so Enter picks it again).
const choices = (els: Els, id: string, options: readonly string[], current: unknown, pick: (value: string) => void) =>
  [...new Set(options.map(String))].map(o =>
    o === String(current) ? (
      <els.Box key={`${id}=${o}`} flexShrink={0}>
        <els.Text inverse>{` ${o} `}</els.Text>
      </els.Box>
    ) : (
      <els.Button key={`${id}=${o}`} plain dimColor label={o} onPress={() => pick(o)} />
    ),
  )

export function panelView(els: Els, props: RenderInput<'Pane'>['props'], data: PanelData, act: PanelActs) {
  const { Box, Text, Button, Input } = els
  const { plugins, sections, commands, note } = data
  const cols = Math.max(30, props.bodyColumns - EDGE)
  const nameWidth = Math.min(24, Math.floor(cols / 3))
  const toggles = plugins.filter(p => !p.isSelf)
  // Hotkeys follow the drawn order: the sections', then each section's fields'.
  const switches = sections.flatMap(s => s.fields.filter(f => f.type === 'boolean').map(f => `${s.group}:${f.key}`))

  const rule = (key: string) => (
    <Box key={key} height={1} overflow="hidden">
      <Text color={P.dim}>{'─'.repeat(400)}</Text>
    </Box>
  )
  // The title never gives up a column to its subtitle (a long settings path is cut instead).
  const title = (text: string, sub: string) => (
    <Box flexDirection="row" columnGap={1}>
      <Box key={`title:${text}`} flexShrink={0}>
        <Text bold color={P.accent}>
          {text}
        </Text>
      </Box>
      <Box flexShrink={1} overflow="hidden">
        <Text color={P.dim} wrap="truncate-end">
          {sub}
        </Text>
      </Box>
    </Box>
  )
  // One line: indent, a fixed name column, the middle cut to fit, the controls on the right.
  const row = (key: string, name: string, middle: RenderChildren, right?: RenderChildren, nameColor?: string) => (
    <Box key={key} flexDirection="row" height={1}>
      <Box width={2} flexShrink={0} />
      <Box width={nameWidth} flexShrink={0} overflow="hidden">
        <Text color={nameColor} wrap="truncate-end">
          {name}
        </Text>
      </Box>
      <Box flexGrow={1} flexShrink={1} overflow="hidden">
        {middle}
      </Box>
      {right !== undefined && (
        <Box flexShrink={0} flexDirection="row" columnGap={1} marginLeft={2}>
          {right}
        </Box>
      )}
    </Box>
  )
  // The state as an inverse pill, then a dim Button for the other state.
  const switcher = (key: string, isOn: boolean, hotkey: string | undefined, flip: () => void) => [
    <Box key={`${key}-pill`} width={5}>
      <Text inverse color={isOn ? P.ok : P.secondary}>
        {isOn ? ' on ' : ' off '}
      </Text>
    </Box>,
    <Box key={`${key}-box`} width={hotkey ? 6 : 3}>
      <Button key={key} plain dimColor hotkey={hotkey} label={isOn ? 'off' : 'on'} onPress={flip} />
    </Box>,
  ]
  // A boolean flips through the group's set; a choice picks an option; a number or string is typed, Enter saves
  // it as typed: the group's `set` validates and refuses what does not fit (its reason lands in the note).
  const control = (group: string, f: Field) => {
    const id = `set:${group}:${f.key}`
    if (f.type === 'boolean') {
      return switcher(id, f.value === true, LETTERS[switches.indexOf(`${group}:${f.key}`)], () => act.set(group, f.key, f.value !== true))
    }
    if (f.options && f.options.length > 0) return choices(els, id, f.options, f.value, v => act.set(group, f.key, v))
    if (f.type === 'number' || f.type === 'string') {
      return (
        <Box width={Math.min(24, Math.floor(cols / 3))}>
          <Input
            key={fieldKey(id)}
            placeholder="enter saves"
            value={String(f.value ?? '')}
            onSubmit={value => {
              entered[id] = (entered[id] ?? 0) + 1
              act.set(group, f.key, value)
            }}
          />
        </Box>
      )
    }
    return <Text color={P.bad}>unsupported type {f.type}</Text>
  }
  const sign = /^[✓✗]/.exec(note)?.[0]
  const keys = [
    toggles.length > 0 ? `1-${Math.min(PLUGIN_KEYS, toggles.length)} plugin` : '',
    switches.length > 0 ? `a-${LETTERS[Math.min(switches.length, LETTERS.length) - 1]} setting` : '',
    'tab move',
    'q close',
  ].filter(Boolean)

  return (
    <Box flexDirection="column" paddingRight={EDGE} minHeight={props.placement === 'dock' ? props.scroll.bodyRows : undefined}>
      <Box flexDirection="row">
        <Box flexGrow={1} flexShrink={1} overflow="hidden">
          <Text wrap="truncate-end">
            <Text bold color={P.accent}>
              ✚ junkd
            </Text>
            {'  '}
            <Text color={P.secondary}>{`${data.marketplace} ${data.version}`.trim()}</Text>
          </Text>
        </Box>
        <Box flexShrink={0} marginLeft={2}>
          <Button key="close" plain hotkey="q" label="×" dimColor onPress={act.close} />
        </Box>
      </Box>
      {rule('rule-top')}

      <Box flexDirection="column" flexGrow={1} marginTop={1} gap={1}>
        <Box flexDirection="column">
          {title('Plugins', `user scope, ${data.settingsPath}`)}
          {plugins.map(p =>
            row(
              `plugin-row:${p.name}`,
              p.name,
              <Text color={P.secondary} wrap="truncate-end">
                {p.isActive && !p.isUserOn && !p.isSelf ? '(on in this project) ' : ''}
                {p.description}
              </Text>,
              p.isSelf
                ? [
                    <Box key="self" width={12}>
                      <Text color={P.dim}>this pane</Text>
                    </Box>,
                  ]
                : switcher(`plugin:${p.name}`, p.isUserOn, toggles.indexOf(p) < PLUGIN_KEYS ? String(toggles.indexOf(p) + 1) : undefined, () =>
                    act.togglePlugin(p.name),
                  ),
            ),
          )}
          {data.isChanged && row('reload', '', <Text color={P.warn}>run /reload-plugins to apply</Text>)}
        </Box>

        <Box flexDirection="column">
          {title('Settings', `the main settings of ${data.groups.join(', ')}`)}
          {sections.length === 0 && row('no-settings', '', <Text color={P.dim}>reading…</Text>)}
          {sections.map(s => (
            <Box key={`group:${s.group}`} flexDirection="column" marginTop={1}>
              {rule(`rule:${s.group}`)}
              <Box flexDirection="row" height={1} paddingLeft={2}>
                <Box flexGrow={1}>
                  <Text bold color={P.accent}>
                    {s.group}
                  </Text>
                </Box>
                {s.hasPane && <Button key={`pane:${s.group}`} plain dimColor label="settings ▸" onPress={() => act.openPane(s.group)} />}
              </Box>
              {s.fields.map(f => row(`setting:${s.group}:${f.key}`, f.key, <Text wrap="truncate-end">{f.title}</Text>, control(s.group, f)))}
            </Box>
          ))}
        </Box>

        <Box flexDirection="column">
          {title('Commands', 'slash commands of the enabled plugins')}
          {commands.length === 0 && row('no-commands', '', <Text color={P.dim}>No commands.</Text>)}
          {commands.map(c =>
            row(
              `cmd:${c.name}`,
              `/${c.name}`,
              <Text color={P.dim} wrap="truncate-end">
                {c.description}
              </Text>,
              undefined,
              P.secondary,
            ),
          )}
        </Box>
      </Box>

      <Box flexDirection="column" marginTop={1}>
        <Box key="note" height={1} overflow="hidden">
          <Text color={P.secondary} wrap="truncate-end">
            {sign ? <Text color={sign === '✓' ? P.ok : P.bad}>{sign}</Text> : null}
            {sign ? note.slice(1) : note}
          </Text>
        </Box>
        {rule('rule-bottom')}
        <Text color={P.secondary} wrap="truncate-end">
          <Text bold>keys</Text> {keys.join('  ')}
        </Text>
      </Box>
    </Box>
  )
}

